package com.eidolon.sc.mobile;
import android.media.*;import android.os.SystemClock;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import org.json.*;
/** Optional HTTPS multipart ASR adapter. Bounded PCM/WAV lives in memory, never in an audio file. */
final class CallHttpAsr {
 interface Listener{void ready();void ended(long firstVoiceMono,long lastVoiceMono);void result(String text);void error();default void diagnostic(JSONObject data){} default void phase(String phase){} default void warning(String message){} default void error(String message){error();}}
 volatile boolean cancelled,manualFinish;String mode="thinking";CallHttpAsr mode(String value){mode=CallTurnEnd.validMode(value);return this;}void finish(){manualFinish=true;}volatile AudioRecord record;volatile HttpURLConnection connection;
 void cancel(){cancelled=true;HttpURLConnection c=connection;if(c!=null)c.disconnect();AudioRecord r=record;if(r!=null)try{r.stop();}catch(Exception ignored){}}
 static String endpoint(String raw)throws Exception{URL u=new URL(raw);if(!u.getProtocol().equals("https")||u.getUserInfo()!=null||u.getHost().isEmpty()||u.getQuery()!=null||u.getRef()!=null)throw new Exception("识别接口须为不含密钥和查询参数的完整HTTPS转录地址");return u.toString();}
 void run(String address,String model,String key,Listener listener){AudioRecord r=null;AsrDiagnostic diagnostic=new AsrDiagnostic("http",model,"configured",java.util.UUID.randomUUID().toString());String stage="capture";try{listener.diagnostic(diagnostic.stage(stage,"",""));
  int min=AudioRecord.getMinBufferSize(16000,AudioFormat.CHANNEL_IN_MONO,AudioFormat.ENCODING_PCM_16BIT);if(min<=0)throw new IOException();r=new AudioRecord(MediaRecorder.AudioSource.VOICE_COMMUNICATION,16000,AudioFormat.CHANNEL_IN_MONO,AudioFormat.ENCODING_PCM_16BIT,Math.max(min,6400));record=r;if(cancelled)return;if(r.getState()!=AudioRecord.STATE_INITIALIZED)throw new IOException();r.startRecording();if(r.getRecordingState()!=AudioRecord.RECORDSTATE_RECORDING)throw new IOException();listener.ready();ByteArrayOutputStream pcm=new ByteArrayOutputStream();short[] chunk=new short[1600];long start=SystemClock.elapsedRealtime(),lastVoice=0,firstVoice=0;int voiced=0;CallTurnEnd turn=new CallTurnEnd(mode,start);CallTurnEnd.Activity activity=new CallTurnEnd.Activity();String phase="";
  while(!cancelled&&SystemClock.elapsedRealtime()-start<CallTurnEnd.MAX_CAPTURE){int n=r.read(chunk,0,chunk.length);if(n<=0)throw new IOException();double sum=0;for(int i=0;i<n;i++)sum+=(double)chunk[i]*chunk[i];boolean speech=activity.speech(Math.sqrt(sum/n));long now=SystemClock.elapsedRealtime();if(speech){if(firstVoice==0)firstVoice=now;lastVoice=now;turn.voice(now);voiced+=n;}if(lastVoice>0){for(int i=0;i<n;i++){pcm.write(chunk[i]&255);pcm.write((chunk[i]>>8)&255);}}if(lastVoice==0&&now-start>12000)throw new IOException();if(manualFinish)turn.finish();String next=turn.phase(now);if(!next.equals(phase)){phase=next;listener.phase(next);}if(turn.finishAt(now))break;}
  if(turn.limit(SystemClock.elapsedRealtime()))listener.warning("本轮达到60秒采音上限，已保留本轮音频用于一次转录");listener.phase("confirming");if(cancelled)return;if(voiced<4800)throw new IOException();r.stop();r.release();record=null;r=null;listener.ended(firstVoice,lastVoice);byte[] wav=wav(pcm.toByteArray());String boundary="Eidolon"+java.util.UUID.randomUUID().toString().replace("-","");ByteArrayOutputStream body=new ByteArrayOutputStream();String part="--"+boundary+"\r\nContent-Disposition: form-data; name=\"model\"\r\n\r\n"+model+"\r\n--"+boundary+"\r\nContent-Disposition: form-data; name=\"file\"; filename=\"speech.wav\"\r\nContent-Type: audio/wav\r\n\r\n";body.write(part.getBytes(StandardCharsets.UTF_8));body.write(wav);body.write(("\r\n--"+boundary+"--\r\n").getBytes(StandardCharsets.UTF_8));
  stage="request";listener.diagnostic(diagnostic.stage(stage,"",""));if(cancelled)return;HttpURLConnection c=(HttpURLConnection)new URL(endpoint(address)).openConnection();connection=c;c.setInstanceFollowRedirects(false);c.setRequestMethod("POST");c.setConnectTimeout(20000);c.setReadTimeout(60000);c.setDoOutput(true);c.setRequestProperty("Content-Type","multipart/form-data; boundary="+boundary);c.setRequestProperty("Authorization","Bearer "+key);byte[] payload=body.toByteArray();c.setFixedLengthStreamingMode(payload.length);if(cancelled)return;try(OutputStream o=c.getOutputStream()){o.write(payload);}int status=c.getResponseCode();if(status<200||status>=300){listener.diagnostic(diagnostic.stage("service_error","HTTP"+status,c.getHeaderField("x-request-id")));throw new IOException("HTTPS识别服务返回HTTP"+status+"；未自动重试");}String response=new String(StoryFiles.read(c.getInputStream(),128*1024),StandardCharsets.UTF_8);String text=new JSONObject(response).getString("text").trim();if(text.isEmpty()||text.length()>6000)throw new IOException();if(!cancelled){listener.diagnostic(diagnostic.stage("completed","",c.getHeaderField("x-request-id")));listener.result(text);}
 }catch(SecurityException denied){if(!cancelled){listener.diagnostic(diagnostic.stage("permission_denied","PERMISSION_DENIED",""));listener.error("麦克风权限已撤销，请重新授权后手动聆听");}}catch(Exception e){if(!cancelled){listener.diagnostic(diagnostic.stage(stage+"_failed",diagnostic.data.optString("error_code").isEmpty()?e.getClass().getSimpleName():diagnostic.data.optString("error_code"),diagnostic.data.optString("request_id")));listener.error(e.getMessage()!=null&&e.getMessage().startsWith("HTTPS识别服务返回HTTP")?e.getMessage():e instanceof java.net.SocketTimeoutException?"HTTPS识别超时，结果未知；未自动重试": "HTTPS识别未完成，请检查网络、接口或本轮有效讲话；未自动重试");}}finally{record=null;if(r!=null){try{r.stop();}catch(Exception ignored){}r.release();}HttpURLConnection c=connection;connection=null;if(c!=null)c.disconnect();}}
 static byte[] wav(byte[] pcm)throws Exception{java.nio.ByteBuffer b=java.nio.ByteBuffer.allocate(44+pcm.length).order(java.nio.ByteOrder.LITTLE_ENDIAN);b.put("RIFF".getBytes("US-ASCII")).putInt(36+pcm.length).put("WAVEfmt ".getBytes("US-ASCII")).putInt(16).putShort((short)1).putShort((short)1).putInt(16000).putInt(32000).putShort((short)2).putShort((short)16).put("data".getBytes("US-ASCII")).putInt(pcm.length).put(pcm);return b.array();}
}
